from build import save
rows=[
(141,['天狂率旧四人与11名熟识成员回归，现有团队27人；萧翎任副团协调，装备共享后赴下水道磨合。'],['临时熟人队转为中型固定团。'],[],5498,5513),
(142,['天诚与白雌猎豹小雪登场；三贼侦察、双盾开路。提莫斯问是否杀奥斯林兰，回答是后领路并发布任务，亲述旧事证明其身份关联。'],['敌对NPC转为暂时任务伙伴。'],['提莫斯动机是否可信？'],5521,5572),
(143,['提莫斯开暗门进入修道院，许诺阿卡德荣耀项链；说明本命骷髅与弱期，利用玩家调虎并谎报守卫强度。罗格眼代盗贼探路；双盾卡位清强化精英时团队议定高法系比例、动态贡献分装及药师补偿。奥斯林兰到场。'],['暗门猜测得到验证；团队开始制度化分工。'],['阿卡德项链为何在提莫斯手里？','奥斯林兰为何不惧本命被寻？'],5578,5680),
(144,['奥斯林兰见塔布雷特杖短暂回忆并称其爱人，随即被邪神印记再控。牧寒盾碎身死，浴血战复，萧翎提出有图可锻造并加工程符文。'],['奥斯林兰对塔的情感得到直接言行证据；盾稀缺变为团队补给议题。'],['寻找盾图纸。'],5687,5723),
(145,['霏雨及时救萧翎。提莫斯拿本命骷髅到场，奥斯林兰引燃其中灵魂诅咒使二者同死。她获神宽恕而提莫斯被虚空吞噬；杖上祈祷仍愿代其受罚。天狂得荣耀项链、霏雨得奥杖；修道院崩塌。'],['奥斯林兰与提莫斯线终结。'],[],5729,5771),
(146,['萧翎决定主转机械，因不愿将未来绑定有变数的戒指；拟访阿卡德询项链。浴血提醒霏雨不能因照顾萧翎忽略盾。佣兵会说明唯一任务可事后领奖，萧翎因30经验锁暂退。'],['转职路线明确；公共名声成为招募资源。'],['鉴定师任务书籍未齐如何结算？'],5775,5811),
(147,['领取3万金、30万团队经验及米修盾战护腿，无炎优先获装。阿卡德证实项链是提莫斯偷走、塔因此独赴修道院，仍赠团队并告知五件套共鸣。天狂只招法系，立一个月人品考核。'],['项链起源回收；固定团以信任与能力筛选。'],['余四套件待寻。'],5816,5851),
(148,['林菲以盗贼PK检验法师30秒自保，1800输出炼天失败，另一火法过关。萧翎带夜落十余种药离队转职，路见七万坐骑而钱不足。'],['自保标准落实为招募测试；主角单独行动。'],[],5855,5899),
(149,['回艾丁斯途中见战痕想象未来大战；夜间遇曾秒自己的格鲁高之子，四控轮替复仇，并发现远距离抗拒光环可被躲。'],['旧压迫怪成为成长对照，同时校正控制规则。'],[],5904,5937),
(150,['格鲁高之子掉月亮晶石，主角拟给月落；城门未开挖矿等候。向马尔都克承认缺材料，掺杂戒指真实封印编造黑焰追查威慑，老者不敢罚级。'],['信息劣势被真实物证与虚构权威逆转。'],['月亮晶石用途。'],5941,5981),
(151,['主角故意说向黑焰问书，迫老者改口；以七家族关联逼出艾尔兰提项链，再得符文、魔法阵、炼阵三本入门书。任务消除并绑定项链，书暂存。'],['旧任务以谈判结算，召炎魔与工程知识获得。'],['马尔都克暂忌惮但仍有敌意。'],5985,6026),
(152,['传送5000太贵，改付100乘蝙蝠三小时至雷诺斯；同行毁术舒眉介绍努尔库勒与科技神南纳。'],['地理扩展到转职城，交通成本限制行动。'],[],6030,6075),
(153,['穿机械袍携傀儡登9999阶。阿普苏主持转职，主角选s级以减少赌博损失但因多职业加难。拒两名同伴。地图击杀不掉级、10%掉传说以上装、战报公开，可联盟。'],['转职变成玩家竞争；阿普苏身份仅主角疑似神。'],['阿普苏真实身份。'],6080,6114),
(154,['传说以上装被爆光则出局，预计两三周。迷幻之地四营，需杀5沉沦魔巫师；火免与巫师复活战士要求择目标。石像鬼警戒黑蟒后，主角遭三人偷袭，四控配逃。'],['单人路线遭复数玩家风险实证。'],[],6118,6168),
(155,['主角尾随报复，等盗贼离队，用傀儡包抄逐个杀三人，获霍尔兹龙鳞铠甲拟给无炎。隐缝睡三小时，以傀儡警戒。'],['被追猎者反成猎人，获团队坦装。'],[],6172,6216),
(156,['侦察俊美痛术认为其沉稳而避战，耐心杀3巫师。却被该玩家先诅咒偷袭，解咒药救命，放弃攻击未换安全。'],['前判风险成立但回避不能免战；任务进度3/5。'],[],6220,6249),
(157,['双方法系拉扯，主角判断对手等援，承伤逼近、恐惧加虚无避致死魔法，再冰冻击杀。来援牧师是钟店见过的花舞、48级榜二；倒地痛术是其弟流觞。'],['临敌实名关联；主角承认胜流觞有侥幸。'],[],6253,6288),
(158,['主角不信任姐弟拒组，召500攻5000血三分钟炎魔。花舞召低阶守护天使菲儿，以等级/技能压倒主角但停杀邀请，复流觞并组队。'],['失败后以克制建立合作入口；守护天使非战天使。'],[],6292,6337),
(159,['流觞尊重实力无怨，三人约按需冲突PB；姐弟任务杀100巫师。主角坦白四职但保留技术细节，拒入圣殿之火。花舞谈开服仅其队7人到30，主角重审追第一目标。三人包抄攻击另一队。'],['临时联盟形成；顶尖团队差距具体化。'],[],6341,6381),
(160,['三人八秒击一队；另一战中流觞按倒女牧雨蝶阻法使其受辱哭泣，花舞安抚归还其兄装备、流觞道歉。继续袭队得三传说，主角分奥托姆靴。'],['流觞对雨蝶生特别兴趣；主角五件传说。'],['花舞如何精准感知各队？'],6385,6454),
]
d={
'worldbuilding':[['唯一任务可未接先做后领；30级未转职经验锁。','fact',[146,5802,5811]],['迷幻图击杀玩家不掉级，10%爆高装，全高装被爆完出局；怪火免且巫师复活战士。','fact',[153,6112,6114],[154,6118,6133]],['守护天使是低阶守护意识而非代表国家的战天使，角色对强度的初判被修正。','fact',[158,6313,6319]]],
'characters':[['萧翎选机械主职的理由含对戒指依赖风险的顾虑，选低档任务又为尽快回团，成长目标开始受关系与风险管理制约。','fact',[146,5775,5777],[153,6101,6103]],['无炎从贵重护腿无条件优先分配中感受信任，资源分配承担人物留队因果。','fact',[147,5829,5833]],['花舞以压倒实力停杀招募并承认队友分配权益；善意与主动猎杀并存。','fact',[158,6330,6337],[160,6437,6447]]],
'plot':[['本命骷髅似提莫斯的胜机，实为奥斯林兰预设同死机关，回扣她不慌与其自利。','fact',[143,5673,5680],[145,5742,5749]],['项链先作奖励、再作提问契机，最终回收塔进入修道院的因果并开启套装搜寻。','inference',[146,5778,5780],[147,5834,5838]],['旧日秒杀怪重现，主角胜利同时暴露技能可躲限制，避免只展示数值升级。','inference',[149,5919,5937]]],
'style':[['悲剧高潮以遗物铭文补最后祈祷，并连续作者感叹与祈愿放大哀感；明说评价较多，模仿应节制。','inference',[145,5755,5771]],['交通摊贩长夸赞后报七万，传送5000对飞行100，用报价反差和旁人反应制造轻喜。','inference',[148,5895,5899],[152,6033,6050]],['女性凝视、性玩笑与受辱场景被轻喜化，属于源作价值框架，不能直接当原创关系范本。','inference',[160,6393,6406],[160,6422,6451]]],
'narrative':[['阿普苏可能是神仅为主角眩晕感与猜测，未获身份确认。','fact',[153,6104,6106]],['马尔都克段交替给主角编剧目的与老者恐惧心理，使读者知骗局而观察奏效。','inference',[150,5963,5975],[151,6017,6018]],['提莫斯称普通精英而实为强化，保留任务提供者可靠度差异。','fact',[143,5626,5635]]],
'dialogue':[['主角赞美老者、主动求罚、欲言又止，表面恭敬的句子实以权威关系威胁；真实封印支撑谎言可信度。','inference',[150,5959,5981],[151,5998,6003]],['花舞邀组被追问信任理由，经验判断不能换取对方信任，直至实力较量与停手才推进关系。','inference',[158,6296,6305],[158,6331,6337]]],
'pacing':[['清守卫的重复战斗容纳团编制、分装与药师成本讨论，使组织建设伴随可预期战斗运行。','inference',[143,5642,5672]],['修道院悲剧后接领奖、招募、离别与交通，再回单人生存，密集战斗与情绪缓冲交替。','inference',[145,5764,5771],[147,5842,5851],[148,5872,5899]],['等待数小时寻落单巫师体现任务时间成本，遭偷袭后紧迫计时迫使冒险强攻。','inference',[156,6231,6244],[157,6262,6274]]],
'themes':[['奥斯林兰的爱、怨、赎罪通过自毁与为背叛者祈祷并置，神裁判又明确拒绝替提莫斯开脱；这是源作叙述判断。','fact',[145,5743,5759]],['个人不败神话被花舞实力差距打破，主角转而承认失败及团队补错价值。','fact',[156,6225,6226],[158,6326,6330]],['临时竞争地图里的互信不能靠美貌与口头经验建立，需要可观察克制及分配承诺。','inference',[158,6296,6304],[159,6341,6346]]],
'continuity':[['旧清剿任务材料未齐，最终不是完整交付：马尔都克改变要求、交奖励并消除任务。','fact',[150,5951,5956],[151,6000,6014]],['罗格眼此前无声音，142回忆明确据口型识别“不是”；不能写成传回声音。','fact',[142,5552,5555]],['提莫斯同名关系由自白实证，本命藏处与暗门得到验证；阿卡德项链盗窃缘由已回收。','fact',[142,5564,5572],[143,5578,5594],[147,5836,5838]]],
}
